"""Source-backed UK ladybird comparisons; no modeled trends or assumed generations."""
import argparse,csv,json,pathlib,shutil
R=pathlib.Path(__file__).resolve().parents[1];P=R/'data/animalstats';p=argparse.ArgumentParser();p.add_argument('--source-root',type=pathlib.Path);a=p.parse_args();S=a.source_root/'ladybird/data' if a.source_root else P/'source/ladybirds-2025'
rows=list(csv.DictReader((S/'ladybird_traits.csv').open(encoding='utf-8-sig')));meta={r['Column name']:r for r in csv.DictReader((S/'metadata.csv').open(encoding='utf-8-sig'))};prey=list(csv.DictReader((S/'prey_list.csv').open(encoding='utf-8-sig')))
d={k:[]for k in ['animals','traits','values','sources','photos']};sid='uk-ladybird-traits-2025';d['sources'].append(dict(id=sid,name='Outhwaite et al. · UK ladybird trait database',url='https://doi.org/10.5285/18cdeee4-38cf-4d15-a141-a99a53e17095',versionYear='2025; occurrence records 1970–2023',retrievedAt='2026-10-12',license='Open Government Licence; cite Outhwaite et al. 2025',sourceClass='curated-trait-database'))
metrics=[('body','Longest body','Shortest body','mm','insect-body-length','anatomy','Body_size_max','intuitive','Upper endpoint of the published adult body-length range in the 2025 UK ladybird trait database. Original lower endpoint retained. This is a reported field-guide/literature endpoint, not an estimated wing measurement or typical individual size.'),('diet','Most varied recorded diet','Least varied recorded diet','recorded food families','documented-food-diversity','diet','nfamilies_diet','intuitive','Number of different food families documented for this ladybird in Outhwaite et al. 2025. Includes published larval and/or adult feeding records and can include plants and fungi. Only medium or high evidence-confidence species are admitted. This is documented breadth, affected by research effort, not the full diet.'),('habitats','Uses the most habitat types','Uses the fewest habitat types','habitat types','habitat-diversity','environment','n_habitats','intuitive','Number of IUCN Level 1 habitat types in which the UK ladybird database records this species commonly or occasionally. Each habitat counts once. Literature and expert-validated classifications; this is not mapped area or abundance.'),('sightings','Most sightings in UK survey','Fewest sightings in UK survey','verified records','recorded-observations','range-geography','n_records','specialist','Number of verified UK species occurrence records from the UK Ladybird Survey and iRecord used by Outhwaite et al. 2025, restricted to 1970–2023 and dated precise locations. This measures records in a specific survey; recorder effort and detectability matter. It is not number of animals alive.'),('spread','Most widespread in UK survey','Least widespread in UK survey','10-km grid cells','recorded-range','range-geography','n_10k','intuitive','Number of UK 10-kilometre Ordnance Survey grid cells with at least one verified record of this species in the 1970–2023 dataset. This is observed UK survey coverage, not its complete global range or a modeled distribution.')]
for m,hi,lo,unit,key,fam,field,kind,basis in metrics:
 for suffix,label,di,other in [('',hi,'higher_wins','__low'),('__low',lo,'lower_wins','')]:
  d['traits'].append(dict(id='ladybird_'+m+suffix,displayName=label,unit=unit,metricKey=key,gameplayFamily=fam,measurementBasis=basis,definition=basis,canonicalSourceId=sid,eligibilityGroups=['insect'],categoryKind=kind,prototypeCategory=True,direction=di,counterTraitId='ladybird_'+m+other,separationMethod='positive_ratio_5_percent'))
for r in sorted(rows,key=lambda r:(r['Conspicuous']!='Conspicuous',-int(r['n_records']))):
 name=r['Genus']+' '+r['Species'];aid=name.lower().replace(' ','_');common=r['Common_name'];d['animals'].append(dict(id=aid,scientificName=name,commonName=common,entityType='species',taxonomicGroup='insect',familiarityTier='core'if r['Conspicuous']=='Conspicuous'else'familiar',active=True))
 for m,hi,lo,unit,key,fam,field,kind,basis in metrics:
  if m=='diet'and r['Foodguild_confidence']not in['Medium','High']:continue
  try:n=float(r[field])
  except ValueError:continue
  if n<=0:continue
  for suffix in ['', '__low']:
   extra={'reportedBodyLengthMinimumMm':float(r['Body_size_min'])}if m=='body'else{}
   d['values'].append(dict(animalId=aid,traitId='ladybird_'+m+suffix,valueNumeric=n,unit=unit,measurementBasis=basis,sourceId=sid,sex='species-level',lifeStage='adult'if m=='body'else'species record',confidence='approved',observationType='compiled',uncertaintyStatus='not-reported',notes=f"Outhwaite et al. 2025; exact species {name}, authority {r['Authority']}; ladybird_traits.csv field {field}; field provenance: {meta[field]['Sources']}. Diet confidence {r['Foodguild_confidence']}, {r['nfood_recs']} food records. Original food source bibliography and prey family table are frozen with the data. No modeled occupancy trend, temperature estimate or assumed voltinism imported.",**extra))
