if old.exists():d['photos']=json.loads(old.read_text())['photos']
old.write_text(json.dumps(d,separators=(',',':'))+'\n');dest=P/'source/ladybirds-2025';dest.mkdir(exist_ok=True)
for file in S.glob('*.csv'):
 if file.resolve()!=(dest/file.name).resolve():shutil.copyfile(file,dest/file.name)
